L12_1.m_CharStrID = L13_1
L12_1.m_Pos = "C"
L13_1 = "\234\183\184 \235\130\152\235\172\180\235\138\148 \235\130\180 \236\139\172\236\158\165\236\151\144 \235\176\149\237\158\140 \234\178\131\234\179\188 \234\176\153\236\157\128, \237\153\169\234\184\136\235\130\152\235\172\180\235\157\188 \235\182\136\235\166\172\235\138\148 \236\132\184\236\131\129\236\157\152 \234\184\176\235\145\165."
L12_1.m_Talk_KOREA = L13_1
L12_1.m_fTalkTime = 0.03
L13_1 = "\227\129\130\227\129\174\230\156\168\227\129\175\231\167\129\227\129\174\229\191\131\232\135\147\227\129\171\229\136\186\227\129\149\227\129\163\227\129\166\227\129\132\227\130\139\227\130\130\227\129\174\227\129\168\229\144\140\227\129\152\227\128\129\233\187\132\233\135\145\227\129\174\230\156\168\227\129\168\229\145\188\227\129\176\227\130\140\227\130\139\228\184\150\231\149\140\227\129\174\230\159\177\227\128\130"
L12_1.m_Talk_JPN = L13_1
L13_1 = "That tree is the pillar of the world called the Golden Tree, the same one embedded in my heart."
L12_1.m_Talk_ENG = L13_1
L13_1 = "\233\130\163\230\163\181\230\168\185\230\152\175\232\178\171\231\169\191\230\136\145\229\191\131\232\135\159\227\128\129\229\144\141\231\130\186\233\187\131\233\135\145\230\168\185\231\154\132\228\184\150\231\149\140\230\148\175\230\159\177\227\128\130"
