L14_1 = "\236\154\176\235\166\172\235\143\132 \235\168\188 \234\179\188\234\177\176\236\151\148, \234\183\184 \235\130\152\235\172\180\235\165\188 \235\145\152\235\159\172\236\139\188 \235\130\153\236\155\144\236\151\144\236\132\156 \234\183\184 \234\184\136\235\185\155 \236\157\128\236\180\157\236\157\132 \235\136\132\235\166\172\235\169\176 \236\130\180\236\149\152\236\167\128."
L13_1.m_Talk_KOREA = L14_1
L13_1.m_fTalkTime = 0.03
L14_1 = "\230\136\145\227\128\133\227\130\130\233\129\160\227\129\132\230\152\148\227\129\175\227\128\129\227\129\130\227\129\174\230\156\168\227\130\146\229\155\178\227\130\128\230\165\189\229\156\146\227\129\167\227\128\129\233\135\145\232\137\178\227\129\174\230\129\169\229\175\181\227\130\146\229\143\151\227\129\145\227\129\166\230\154\174\227\130\137\227\129\151\227\129\166\227\129\132\227\129\159\227\128\130"
L13_1.m_Talk_JPN = L14_1
